#!/usr/bin/env node
/**
 * Tests for hooks/context-nudge.js and the snapshot statusline.js writes for it. Zero
 * dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Each case gets its own CLAUDE_CONFIG_DIR, so the snapshot, the band state and the pruning only
 * ever touch a temp directory. The end-to-end case runs the real statusline on a payload and the
 * hook on the file it wrote: the two sides must agree on the path and the shape.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, utimesSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HOOK = join(ROOT, 'hooks', 'context-nudge.js');
const STATUSLINE = join(ROOT, 'statusline.js');
/** The ladder the hook is opted into with in these tests; unset, the hook is off. */
const STEPS = '120000,200000,320000';
const created = [];
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function sandbox() {
  const config = mkdtempSync(join(tmpdir(), 'nudge-'));
  created.push(config);
  mkdirSync(join(config, '.cache'));
  return config;
}

function snapshot(config, id, used_percentage, at = Date.now()) {
  writeFileSync(join(config, '.cache', `context-${id}.json`), JSON.stringify({ used_percentage, warm: true, at }));
}

function tokenSnapshot(config, id, used_tokens, window = 1_000_000, used_percentage = null) {
  writeFileSync(join(config, '.cache', `context-${id}.json`), JSON.stringify({ used_percentage, used_tokens, window, warm: true, at: Date.now() }));
}

function nudge(config, id = 'sess-1') {
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ session_id: id, hook_event_name: 'UserPromptSubmit', prompt: 'x' }),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: STEPS },
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput.additionalContext : '';
}

test('absolute steps: 120k, 200k and 320k fire once each on a 1M window', () => {
  const config = sandbox();
  tokenSnapshot(config, 'sess-1', 100_000);
  assert.equal(nudge(config), '', 'under 120k');
  tokenSnapshot(config, 'sess-1', 150_000);
  assert.match(nudge(config), /^Contesto a 150k token.*\/compact <focus>/);
  assert.equal(nudge(config), '', 'same band: silent');
  tokenSnapshot(config, 'sess-1', 210_000);
  assert.match(nudge(config), /Contesto a 210k token/);
  tokenSnapshot(config, 'sess-1', 330_000);
  assert.match(nudge(config), /Contesto a 330k token/);
});

test('a percentage alone on a 1M window stays silent (15 % is 150k, 50 % would be 500k)', () => {
  const config = sandbox();
  writeFileSync(join(config, '.cache', 'context-sess-1.json'), JSON.stringify({ used_percentage: 60, window: 1_000_000, at: Date.now() }));
  assert.equal(nudge(config), '');
});

test('off by default: without a valid CLAUDE_NUDGE_STEPS the hook is silent, even far past any step', () => {
  const run = (steps) => {
    const config = sandbox();
    tokenSnapshot(config, 'sess-1', 400_000);
    const env = { ...process.env, CLAUDE_CONFIG_DIR: config };
    if (steps === undefined) delete env.CLAUDE_NUDGE_STEPS; else env.CLAUDE_NUDGE_STEPS = steps;
    return spawnSync(process.execPath, [HOOK], { input: JSON.stringify({ session_id: 'sess-1' }), encoding: 'utf8', env }).stdout;
  };
  for (const off of [undefined, '', 'abc', '250000,', '0', '-5']) assert.equal(run(off), '', `"${off}" is off`);
  assert.match(run('250000'), /Contesto a 400k token/, 'a valid value turns it on');
});

test('below 50 % → silent', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 42);
  assert.equal(nudge(config), '');
});

test('crossing 50 / 70 / 85 → one line per band, once', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 51.4);
  assert.match(nudge(config), /^Contesto al 51 %.*\/compact <focus>.*\/clear/);
  assert.equal(nudge(config), '', 'same band: silent');
  snapshot(config, 'sess-1', 72);
  assert.match(nudge(config), /Contesto al 72 %/);
  snapshot(config, 'sess-1', 90);
  assert.match(nudge(config), /Contesto al 90 %/);
  assert.equal(nudge(config), '');
});

test('a jump straight past two bands announces once, at the highest', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 88);
  assert.match(nudge(config), /88 %/);
  snapshot(config, 'sess-1', 89);
  assert.equal(nudge(config), '');
});

test('after /compact the band re-arms silently, then fires again on the next crossing', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 72);
  assert.match(nudge(config), /72 %/);
  snapshot(config, 'sess-1', 12);
  assert.equal(nudge(config), '', 'dropping is not announced');
  snapshot(config, 'sess-1', 55);
  assert.match(nudge(config), /55 %/);
});

test('null percentage, missing, stale or foreign snapshot → silent', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', null);
  assert.equal(nudge(config), '');
  assert.equal(nudge(config, 'other'), '');
  snapshot(config, 'sess-1', 80, Date.now() - 7 * 60 * 60 * 1000);
  assert.equal(nudge(config), '');
  assert.equal(nudge(sandbox(), '../escape'), '');
});

test('parallel sessions keep separate bands', () => {
  const config = sandbox();
  snapshot(config, 'a', 60);
  snapshot(config, 'b', 60);
  assert.match(nudge(config, 'a'), /60 %/);
  assert.match(nudge(config, 'b'), /60 %/);
});

test('old cache files are pruned when a nudge fires', () => {
  const config = sandbox();
  const old = join(config, '.cache', 'context-gone.json');
  writeFileSync(old, '{}');
  const past = (Date.now() - 4 * 24 * 60 * 60 * 1000) / 1000;
  utimesSync(old, past, past);
  snapshot(config, 'sess-1', 60);
  nudge(config);
  assert.ok(!existsSync(old));
  assert.ok(existsSync(join(config, '.cache', 'context-sess-1.json')));
});

test('statusline writes the snapshot the hook reads, null-safe', () => {
  const config = sandbox();
  const render = (payload) => spawnSync(process.execPath, [STATUSLINE], {
    input: JSON.stringify(payload), encoding: 'utf8', env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: STEPS },
  });
  render({ session_id: 'sl-1', cwd: config, context_window: { used_percentage: null } });
  const empty = JSON.parse(readFileSync(join(config, '.cache', 'context-sl-1.json'), 'utf8'));
  assert.equal(empty.used_percentage, null);

  const r = render({
    session_id: 'sl-1', cwd: config,
    context_window: { used_percentage: 73, total_input_tokens: 146000, context_window_size: 200000 },
    prompt_cache: { warm: false, caching_observed: true, recache_tokens_if_cold: 146000 },
  });
  assert.match(r.stdout, /cache cold 146k/);
  const snap = JSON.parse(readFileSync(join(config, '.cache', 'context-sl-1.json'), 'utf8'));
  assert.equal(snap.used_percentage, 73);
  assert.equal(snap.used_tokens, 146000, 'derived from the percentage and the window');
  assert.equal(snap.window, 200000);
  assert.equal(snap.warm, false);
  assert.match(nudge(config, 'sl-1'), /Contesto a 146k token/);
});

test('statusline rewrites the snapshot only when a value changes, or once it is an hour old', () => {
  const config = sandbox();
  const file = join(config, '.cache', 'context-sl-4.json');
  const render = (used_percentage) => spawnSync(process.execPath, [STATUSLINE], {
    input: JSON.stringify({ session_id: 'sl-4', cwd: config, context_window: { used_percentage, context_window_size: 200000 } }),
    encoding: 'utf8', env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: STEPS },
  });
  const stamp = (at) => writeFileSync(file, JSON.stringify({ ...JSON.parse(readFileSync(file, 'utf8')), at }));
  const at = () => JSON.parse(readFileSync(file, 'utf8')).at;

  render(40);
  const marker = Date.now() - 5000;
  stamp(marker);
  render(40);
  assert.equal(at(), marker, 'same values, fresh file: not rewritten');
  render(41);
  assert.ok(at() > marker, 'a changed value is written');
  assert.equal(JSON.parse(readFileSync(file, 'utf8')).used_percentage, 41);
  const old = Date.now() - 2 * 60 * 60 * 1000;
  stamp(old);
  render(41);
  assert.ok(at() > old, 'same values but an hour old: refreshed, so the nudge never sees it as stale');
});

test('statusline: every cache it keeps lives under CLAUDE_CONFIG_DIR, none under the real home', () => {
  const config = sandbox();
  const home = mkdtempSync(join(tmpdir(), 'nudge-home-'));
  created.push(home);
  const env = { ...process.env, CLAUDE_CONFIG_DIR: config, HOME: home, USERPROFILE: home };
  spawnSync(process.execPath, [STATUSLINE], {
    input: JSON.stringify({
      session_id: 'sl-3', cwd: config,
      rate_limits: { five_hour: { used_percentage: 12, resets_at: Date.now() / 1000 + 3600 } },
    }),
    encoding: 'utf8', env,
  });
  assert.ok(existsSync(join(config, '.statusline-rate-limits.json')), 'rate-limit cache in the config dir');
  assert.ok(!existsSync(join(home, '.claude')), 'nothing written under the home .claude');

  // The worklog badge reads its snapshot from the config dir too.
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  writeFileSync(join(config, '.worklog-pending.json'), JSON.stringify({
    day: `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`, auditMtime: 0, pending: [{ date: '2026-01-02' }],
  }));
  const out = spawnSync(process.execPath, [STATUSLINE], { input: JSON.stringify({ session_id: 'sl-3', cwd: config }), encoding: 'utf8', env });
  assert.equal(out.status, 0, out.stderr);
  assert.match(out.stdout, /1d/, 'the badge comes from the config dir snapshot');
});

test('statusline: no cold badge while warm or when caching was never observed', () => {
  const config = sandbox();
  const render = (prompt_cache) => spawnSync(process.execPath, [STATUSLINE], {
    input: JSON.stringify({ session_id: 'sl-2', cwd: config, prompt_cache }),
    encoding: 'utf8', env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: STEPS },
  }).stdout;
  assert.doesNotMatch(render({ warm: true, caching_observed: true, expires_at: Date.now() / 1000 + 300 }), /cache cold/);
  assert.doesNotMatch(render({ warm: false, caching_observed: false }), /cache cold/);
  assert.match(render({ warm: true, caching_observed: true, expires_at: Date.now() / 1000 - 5 }), /cache cold/);
});

test('CLAUDE_NUDGE_STEPS sets the steps: one nudge at 250k, none at 120k or 200k', () => {
  const run = (config, steps) => spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ session_id: 'sess-1' }), encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: steps },
  }).stdout;
  const config = sandbox();
  tokenSnapshot(config, 'sess-1', 130_000);
  assert.equal(run(config, '250000'), '', 'under the only step');
  tokenSnapshot(config, 'sess-1', 210_000);
  assert.equal(run(config, '250000'), '');
  tokenSnapshot(config, 'sess-1', 255_000);
  assert.match(run(config, '250000'), /Contesto a 255k token/);
  tokenSnapshot(config, 'sess-1', 280_000);
  assert.equal(run(config, '250000'), '', 'once');
});
